// ======================= SPIKE =======================
const entities: EntityInput[] = [...trials];

const spike: Spike = {
  cancerId: "breast-cancer",
  entities,
  supplements: [
    { id: "jack-cuzick", trials: ["ibis-i", "ibis-ii"] },
    { id: "breast-cancer-now", cancers: ["breast-cancer"] },
  ],
  patch: {
    trials: ["ibis-i", "ibis-ii", "agex", "start-b", "fast-forward", "import-low"],
  },
};

export default spike;
